using Microsoft.EntityFrameworkCore;using OperationsRequests.Data;using OperationsRequests.Domain;namespace OperationsRequests.Services;
public sealed class RequestWorkflowService(ApplicationDbContext db){public async Task<(bool,string)> Act(TrainingRequest r,ApplicationUser u,IList<string> roles,string action,string? note,byte[] version){if(!u.IsActive)return(false,"Account is inactive.");if(!r.RowVersion.SequenceEqual(version))return(false,"Request was changed by another user.");if(r.RequestedById==u.Id&&action is not "ProvideInfo")return(false,"Self-approval is forbidden.");var old=r.Status;var canReviewer=(roles.Contains(Roles.TerritoryManager)&&u.TerritoryId==r.Site.TerritoryId)||(roles.Contains(Roles.CountryOpsManager)&&u.CountryId==r.Site.Territory.CountryId)||roles.Contains(Roles.PlatformAdmin);if(action=="ProvideInfo"){if(r.RequestedById!=u.Id||r.Status!=RequestStatus.AdditionalInfoRequested||string.IsNullOrWhiteSpace(note))return(false,"Only requester may provide a non-empty response.");r.Messages.Add(new RequestMessage{AuthorId=u.Id,Body=note,IsQuestion=false});r.Status=RequestStatus.UnderReview;}else{if(!canReviewer)return(false,"Not authorized for this request scope.");if(action=="StartReview"&&r.Status==RequestStatus.Submitted)r.Status=RequestStatus.UnderReview;else if(action=="RequestInfo"&&r.Status is RequestStatus.UnderReview or RequestStatus.Escalated&&!string.IsNullOrWhiteSpace(note)){r.Messages.Add(new RequestMessage{AuthorId=u.Id,Body=note,IsQuestion=true});r.Status=RequestStatus.AdditionalInfoRequested;}else if(action=="Escalate"&&r.Status==RequestStatus.UnderReview)r.Status=RequestStatus.Escalated;else if(action=="Approve"&&r.Status is RequestStatus.UnderReview or RequestStatus.Escalated){if(r.Priority==RequestPriority.High&&!roles.Contains(Roles.CountryOpsManager)&&!roles.Contains(Roles.PlatformAdmin))return(false,"High priority needs Country Ops final decision.");if(r.Priority!=RequestPriority.High&&!roles.Contains(Roles.TerritoryManager)&&!roles.Contains(Roles.PlatformAdmin))return(false,"Standard request needs Territory Manager.");r.Status=RequestStatus.Approved;}else if(action=="Decline"&&r.Status is RequestStatus.UnderReview or RequestStatus.Escalated&&!string.IsNullOrWhiteSpace(note))r.Status=RequestStatus.Declined;else if(action=="Resolve"&&r.Status==RequestStatus.Approved&&!string.IsNullOrWhiteSpace(note))r.Status=RequestStatus.Resolved;else return(false,"Invalid transition or missing mandatory note.");}
r.Decisions.Add(new RequestDecision{DecidedById=u.Id,Action=action,Note=note??""});r.AuditEvents.Add(new AuditEvent{Action=action,ActorId=u.Id,ActorName=u.DisplayName,PreviousStatus=old,NewStatus=r.Status,Note=note});try{await db.SaveChangesAsync();return(true,"");}catch(DbUpdateConcurrencyException){return(false,"Concurrent update detected.");}catch(DbUpdateException){return(false,"A final decision already exists.");}}}
